package com.miniforce.service;
import com.miniforce.dto.ProblemDtos.*; import com.miniforce.exception.*; import com.miniforce.model.*; import com.miniforce.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class ProblemService {
 private final ProblemRepository problems;private final TopicRepository topics;private final TestCaseRepository cases;private final SubmissionRepository submissions; public ProblemService(ProblemRepository p,TopicRepository t,TestCaseRepository c,SubmissionRepository s){problems=p;topics=t;cases=c;submissions=s;}
 @Transactional(readOnly=true) public List<ProblemSummary> list(String search,Difficulty difficulty,String topic,User viewer){Set<Long> solved=viewer==null?Set.of():submissions.findSolvedProblemIdsByUserId(viewer.getId());boolean isAdmin=viewer!=null&&viewer.getRole()==Role.ADMIN;return problems.search(blank(search),difficulty,blank(topic),isAdmin?null:true).stream().map(p->ProblemSummary.from(p,solved.contains(p.getId()))).toList();}
 @Transactional(readOnly=true) public ProblemDetail get(Long id,User viewer){Problem p=entity(id);if(!Boolean.TRUE.equals(p.getIsPublic())&&(viewer==null||viewer.getRole()!=Role.ADMIN))throw new NotFoundException("Problem not found");return ProblemDetail.from(p);} @Transactional(readOnly=true) public ProblemDetail getBySlug(String slug,User viewer){Problem p=problems.findBySlug(slug).orElseThrow(()->new NotFoundException("Problem not found"));if(!Boolean.TRUE.equals(p.getIsPublic())&&(viewer==null||viewer.getRole()!=Role.ADMIN))throw new NotFoundException("Problem not found");return ProblemDetail.from(p);} public Problem entity(Long id){return problems.findById(id).orElseThrow(()->new NotFoundException("Problem not found"));}
 @Transactional public ProblemDetail create(ProblemRequest r){if(problems.findBySlug(r.slug()).isPresent())throw new ConflictException("Problem slug already exists");Problem p=new Problem();apply(p,r);return ProblemDetail.from(problems.save(p));}
 @Transactional public ProblemDetail update(Long id,ProblemRequest r){Problem p=entity(id);if(!p.getSlug().equals(r.slug())&&problems.findBySlug(r.slug()).isPresent())throw new ConflictException("Problem slug already exists");apply(p,r);return ProblemDetail.from(p);}
 @Transactional public void delete(Long id){problems.delete(entity(id));}
 @Transactional(readOnly=true) public List<TestCaseResponse> testCases(Long problemId){entity(problemId);return cases.findByProblemId(problemId).stream().map(TestCaseResponse::from).toList();} @Transactional(readOnly=true) public List<TestCaseResponse> sampleTestCases(Long problemId){entity(problemId);return cases.findByProblemId(problemId).stream().filter(t->t.isSampleCase()).map(TestCaseResponse::from).toList();}
 @Transactional public TestCaseResponse addTestCase(Long problemId,TestCaseRequest r){TestCase t=new TestCase();t.setProblem(entity(problemId));apply(t,r);return TestCaseResponse.from(cases.save(t));}
 @Transactional public TestCaseResponse updateTestCase(Long id,TestCaseRequest r){TestCase t=cases.findById(id).orElseThrow(()->new NotFoundException("Test case not found"));apply(t,r);return TestCaseResponse.from(t);}
 @Transactional public void deleteTestCase(Long id){if(!cases.existsById(id))throw new NotFoundException("Test case not found");cases.deleteById(id);}
 private void apply(Problem p,ProblemRequest r){p.setSlug(r.slug().trim());p.setTitle(r.title().trim());p.setDifficulty(r.difficulty());p.setDescription(r.description().trim());p.setStarterCode(r.starterCode()==null?"":r.starterCode());p.setConstraintsText(r.constraintsText()==null?"":r.constraintsText());p.setAcceptanceRate(r.acceptanceRate());Set<Topic> set=new LinkedHashSet<>();for(String n:r.topics()==null?Set.<String>of():r.topics()){String clean=n.trim();Topic topic=topics.findByNameIgnoreCase(clean).orElseGet(()->{Topic x=new Topic();x.setName(clean);return topics.save(x);});set.add(topic);}p.setTopics(set);}
 private void apply(TestCase t,TestCaseRequest r){t.setInputData(r.inputData());t.setExpectedOutput(r.expectedOutput());t.setSampleCase(r.sampleCase());} private String blank(String x){return x==null||x.isBlank()?null:x.trim();}
}
